-- Marca los 76 puestos de servicios (S-911..S-986: bancos, telefonia, farmacia,
-- apuestas, libreria, etc.) como 'bloqueado' = espacios institucionales reservados,
-- no disponibles para venta a comerciantes (decision del usuario 2026-11-14).
-- Solo toca los que esten 'disponible' ahora; respeta cualquier venta/separacion en curso.
begin;
lock table public.puestos in share row exclusive mode;
create temporary table _omitidos(codigo text, estado text) on commit drop;
insert into _omitidos select 'S-911', estado from public.puestos where codigo='S-911' and estado<>'disponible';
update public.puestos set estado='bloqueado', motivo_bloqueo='Espacio de servicios institucional - no disponible para venta', version=version+1, actualizado_en=now() where codigo='S-911' and estado='disponible';
