insert into _omitidos select 'S-986', estado from public.puestos where codigo='S-986' and estado<>'disponible';
update public.puestos set estado='bloqueado', motivo_bloqueo='Espacio de servicios institucional - no disponible para venta', version=version+1, actualizado_en=now() where codigo='S-986' and estado='disponible';
do $$ declare v_bloq integer; begin select count(*) into v_bloq from public.puestos where codigo like 'S-9%' and estado='bloqueado'; raise notice '% servicios bloqueados', v_bloq; end $$;
select codigo, estado from _omitidos;
commit;
